contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address from, address to, uint256 amount) public {
        uint256 balBeforeFrom = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 balBeforeTo = c.balanceOf(to); if (__ESBMC_reverted()) return;

        require(balBeforeFrom >= amount, "PRECONDITION_BALANCE");

        c.transfer(to, amount); if (__ESBMC_reverted()) return;

        uint256 balAfterFrom = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 balAfterTo = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(balAfterFrom + balAfterTo == balBeforeFrom + balBeforeTo - amount + amount);
    }

    receive() external payable {}
}

