pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address from, address to, uint256 amount) internal {
        uint256 balBeforeFrom;
        try c.balanceOf(from) returns (uint256 __r) { balBeforeFrom = __r; } catch { return; }
        uint256 balBeforeTo;
        try c.balanceOf(to) returns (uint256 __r) { balBeforeTo = __r; } catch { return; }
        vm.assume(balBeforeFrom >= amount);
        try c.transfer(to, amount) {} catch { return; }
        uint256 balAfterFrom;
        try c.balanceOf(from) returns (uint256 __r) { balAfterFrom = __r; } catch { return; }
        uint256 balAfterTo;
        try c.balanceOf(to) returns (uint256 __r) { balAfterTo = __r; } catch { return; }
        assertTrue(balAfterFrom + balAfterTo == balBeforeFrom + balBeforeTo - amount + amount);
    }

    function testFuzz_run(address from, address to, uint256 amount) public {
        vm.assume(from.code.length == 0 && uint160(from) > 0xffff && from != address(this) && from != address(c) && from != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && from != 0x000000000000000000636F6e736F6c652e6c6f67 && from != 0x4e59b44847b379578588920cA78FbF26c0B4956C && from != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
